"use client";

import Link from "next/link";
import { useState, useEffect } from "react";
import { Github, Linkedin, Mail } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

export function Navbar() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <nav
      className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${
        scrolled ? "bg-background shadow-md" : "bg-transparent"
      }`}
    >
   
       

        {/* Right Side - Avatar and Socials */}
        <div className="flex items-center space-x-4 mt-1"> {/* Avatar moved slightly lower */}
          <Link href="mailto:priyanshu@example.com" aria-label="Email">
            <Mail className="w-5 h-5 hover:text-primary transition" />
          </Link>
          <Link href="https://github.com/yourgithub" target="_blank" aria-label="GitHub">
            <Github className="w-5 h-5 hover:text-primary transition" />
          </Link>
          <Link href="https://linkedin.com/in/yourlinkedin" target="_blank" aria-label="LinkedIn">
            <Linkedin className="w-5 h-5 hover:text-primary transition" />
          </Link>

          {/* Avatar */}
          <Avatar>
            <AvatarImage
              src="/User.jpeg"
              alt="Priyanshu Rajak"
              className="w-10 h-10 rounded-full object-cover"
            />
            <AvatarFallback>PR</AvatarFallback>
          </Avatar>
        </div>
    </nav>
  );
}
